import java.io.*;import java.net.ServerSocket;import java.nio.charset.StandardCharsets;import java.nio.file.*;import java.security.MessageDigest;import java.util.*;import java.util.stream.*;
/** Repeats official redstone-torch burnout 76:4 <-> 75:4 plus recovery. */
public final class TorchBurnoutSetCycle{
 private static final String ID="m555-torch-burnout-set";private final Path root=Paths.get("").toAbsolutePath().normalize(),smoke=root.resolve("smokes").resolve(ID),build=root.resolve(".worldline/smokes").resolve(ID);private final Properties config=new Properties(),artifact=new Properties();
 public static void main(String[]a){if(!Arrays.equals(a,new String[]{ID})){System.err.println("usage: java tools/smoke/TorchBurnoutSetCycle.java "+ID);System.exit(2);}try{new TorchBurnoutSetCycle().execute();}catch(Exception e){System.err.println("torch burnout set failed: "+e.getMessage());System.exit(1);}}
 private void execute()throws Exception{load(smoke.resolve("smoke.properties"),config);load(root.resolve("artifacts/minecraft-b1.7.3-server.properties"),artifact);require(ID.equals(value(config,"id"))&&value(config,"server.jar.sha256").equals(value(artifact,"expected.sha256"))&&value(config,"username").equals("TorchBurn555")&&value(config,"username").length()<=16,"descriptor drift");Path official=root.resolve(value(artifact,"local.path")).normalize();verifyArtifact(official);recreate(build);Path classes=compile();Outcome first=run(classes,official,build.resolve("first")),second=run(classes,official,build.resolve("second"));require(first.signal.equals(second.signal)&&first.trace.equals(second.trace)&&first.signature.equals(second.signature),"fresh torch burnout results diverged");require(first.signal.contains("76:4->75:4->76:4")&&first.signal.contains("burnout=75:4")&&first.signal.contains("recovered=76:4")&&first.signal.contains("persisted=76:4")&&first.signal.contains("rapidActivations=24")&&first.signal.contains("recoveryWait=400")&&!first.signal.contains("76:5")&&first.trace.contains("torch76:4<->torch75:4")&&first.trace.contains("torch76")&&first.trace.contains("torch75")&&!first.signal.contains("76:4->75:4,persisted=true"),"burnout collapsed to M312 invert, M182 floor 76:5, or dropped a state");String expected=value(config,"expected.signature");if(expected.equals("pending")||Boolean.getBoolean("worldline.m555.diagnostic")){freeze(first);System.out.println("M555 torch burnout diagnostic passed; qualification not attempted");System.out.println("  "+first.signal);System.out.println("  trace: "+first.trace);System.out.println("  signature: "+first.signature);return;}require(first.signal.equals(value(config,"expected.signal"))&&first.signature.equals(expected),"M555 frozen evidence drift");Files.writeString(build.resolve("evidence.txt"),"id="+ID+"\nservers=2\nclients=4\nfirst="+first.signal+"\nsecond="+second.signal+"\ntrace="+first.trace+"\nsignature="+first.signature+"\n",StandardCharsets.UTF_8);System.out.println("M555 torch burnout set passed");System.out.println("  "+first.signal);System.out.println("  signature: "+first.signature);System.out.println("FROZEN");}
 private Outcome run(Path classes,Path official,Path workspace)throws Exception{Exception last=null;for(int i=0;i<2;i++){try{if(Files.exists(workspace))recreate(workspace);String output=capture(root,Arrays.asList("java","-classpath",classes+separator()+product("api"),"worldline.smoke.torchburnoutsetb173.TorchBurnoutSetSmoke",official.toString(),workspace.toString(),Integer.toString(freePort()),value(config,"seed"),value(config,"username"),value(config,"chunk.x"),value(config,"chunk.z")));return new Outcome(line(output,"WORLDLINE_M555_TRACE="),line(output,"WORLDLINE_M555_SIGNATURE="),line(output,"WORLDLINE_M555_BURNOUT="));}catch(Exception e){last=e;SmokeRetryBoundary.afterEofFailure(i,1,e);throw e;}}throw last;}
 private Path compile()throws Exception{Path output=build.resolve("adapter-classes");Files.createDirectories(output);List<String>command=new ArrayList<>(Arrays.asList("javac","-encoding","UTF-8","--release","8","-Xlint:all,-options","-Werror","-classpath",product("api").toString(),"-d",output.toString()));command.addAll(javaFiles(root.resolve("modules/smoketest/src/main/java")));command.addAll(javaFiles(root.resolve("adapters/b173-server/src/main/java")));command.addAll(javaFiles(smoke.resolve("src")));capture(root,command);return output;}
 private void freeze(Outcome first)throws Exception{Path file=smoke.resolve("smoke.properties");String text=Files.readString(file,StandardCharsets.UTF_8);text=text.replaceAll("(?m)^expected\\.signal=.*$","expected.signal="+first.signal);text=text.replaceAll("(?m)^expected\\.signature=.*$","expected.signature="+first.signature);Files.writeString(file,text,StandardCharsets.UTF_8);}
 private void verifyArtifact(Path p)throws Exception{require(Files.isRegularFile(p),"server artifact absent");require(Files.size(p)==Long.parseLong(value(artifact,"expected.bytes"))&&digest(p,"SHA-1").equals(value(artifact,"expected.sha1"))&&digest(p,"SHA-256").equals(value(artifact,"expected.sha256")),"server artifact drift");}private List<String>javaFiles(Path s)throws IOException{try(Stream<Path>p=Files.walk(s)){return p.filter(x->x.toString().endsWith(".java")).filter(x->!x.getFileName().toString().equals("B173AtlasRunner.java")).sorted().map(Path::toString).collect(Collectors.toList());}}private String capture(Path d,List<String>c)throws Exception{Process p=new ProcessBuilder(c).directory(d.toFile()).redirectErrorStream(true).start();String o=new String(p.getInputStream().readAllBytes(),StandardCharsets.UTF_8);if(p.waitFor()!=0)throw new IllegalStateException(c.get(0)+" failed\n"+o);return o;}private void recreate(Path t)throws IOException{if(Files.exists(t)){require(t.startsWith(root.resolve(".worldline"))&&!t.equals(root),"unsafe build path");try(Stream<Path>p=Files.walk(t)){for(Path f:p.sorted(Comparator.reverseOrder()).collect(Collectors.toList()))Files.delete(f);}}Files.createDirectories(t);}private void load(Path p,Properties t)throws IOException{try(Reader r=Files.newBufferedReader(p,StandardCharsets.UTF_8)){t.load(r);}}private String value(Properties p,String k){String v=p.getProperty(k);require(v!=null&&!v.trim().isEmpty(),"missing "+k);return v.trim();}private String digest(Path p,String a)throws Exception{MessageDigest d=MessageDigest.getInstance(a);try(InputStream in=Files.newInputStream(p)){byte[]b=new byte[8192];int n;while((n=in.read(b))>=0)d.update(b,0,n);}return HexFormat.of().formatHex(d.digest());}private int freePort()throws IOException{try(ServerSocket s=new ServerSocket(0)){return s.getLocalPort();}}private Path product(String n){return root.resolve(".worldline/build/classes").resolve(n);}private String separator(){return System.getProperty("path.separator");}private String line(String o,String p){return o.lines().filter(x->x.startsWith(p)).findFirst().orElseThrow(()->new IllegalStateException("missing "+p+"\n"+o)).substring(p.length());}private static void require(boolean v,String m){if(!v)throw new IllegalStateException(m);}private static final class Outcome{final String trace,signature,signal;Outcome(String t,String s,String l){trace=t;signature=s;signal=l;}}
}
